(function(){'use strict';
const bank=window.ScienceCards||[], storageKey='one-bite-science-cards-v1';let category='all',deck=bank.slice(),index=0,selected=null,saved=new Set(),seen=new Set(),storageOK=true;
const $=s=>document.querySelector(s),safe=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const stored=JSON.parse(localStorage.getItem(storageKey)||'{}');const ids=new Set(bank.map(c=>c.id));saved=new Set((Array.isArray(stored.saved)?stored.saved:[]).filter(id=>ids.has(id)));seen=new Set((Array.isArray(stored.seen)?stored.seen:[]).filter(id=>ids.has(id)));}catch{storageOK=false;}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({saved:[...saved],seen:[...seen]}));}catch{storageOK=false;}counters();}
function counters(){$('#seen-count').textContent=seen.size;$('#saved-count').textContent=saved.size;if(!storageOK)$('#storage-note').textContent='当前浏览器无法保存，记录只保留到关闭页面。';}
function filterDeck(){deck=bank.filter(c=>category==='all'||(category==='saved'?saved.has(c.id):c.category===category));index=0;selected=null;render();}
function render(){selected=null;const c=deck[index];$('#deck-position').textContent=c?`${category==='all'?'全部知识卡':category==='saved'?'我的收藏':category} · ${index+1} / ${deck.length}`:'这里暂时还没有卡片';$('#prev-card').disabled=index===0;$('#next-card').disabled=index>=deck.length-1;$('#shuffle-deck').disabled=deck.length<2;
if(!c){$('#deck').innerHTML='<div class="card-empty"><span>♡</span><h2>把喜欢的问题收藏起来。</h2><p>在知识卡右上角点一下爱心，就会出现在这里。</p></div>';counters();return;}
$('#deck').innerHTML=`<div class="card-category">${safe(c.category)}<span>${safe(c.difficulty)}</span>${c.fictional?'<span>虚构教学情境</span>':''}</div><button class="save-card" aria-label="${saved.has(c.id)?'取消收藏':'收藏这张卡片'}" aria-pressed="${saved.has(c.id)}">${saved.has(c.id)?'♥':'♡'}</button><h2>${safe(c.prompt)}</h2><div class="card-choices" role="group" aria-label="选择你的判断">${c.choices.map((t,i)=>`<button data-choice="${i}"><span>${String.fromCharCode(65+i)}</span>${safe(t)}</button>`).join('')}</div><div class="card-explanation" hidden></div>`;counters();}
$('#deck').addEventListener('click',e=>{const c=deck[index];if(!c)return;if(e.target.closest('.save-card')){if(saved.has(c.id))saved.delete(c.id);else saved.add(c.id);persist();if(category==='saved'&&!saved.has(c.id)){deck=deck.filter(x=>x.id!==c.id);index=Math.max(0,Math.min(index,deck.length-1));render();}else{const b=$('.save-card');b.textContent=saved.has(c.id)?'♥':'♡';b.setAttribute('aria-pressed',saved.has(c.id));b.setAttribute('aria-label',saved.has(c.id)?'取消收藏':'收藏这张卡片');}return;}const button=e.target.closest('[data-choice]');if(!button||selected!==null)return;selected=Number(button.dataset.choice);seen.add(c.id);persist();document.querySelectorAll('[data-choice]').forEach((b,i)=>{b.disabled=true;b.classList.toggle('correct',i===c.answerIndex);b.classList.toggle('wrong',i===selected&&i!==c.answerIndex);});const area=$('.card-explanation');area.hidden=false;area.innerHTML=`<strong>${selected===c.answerIndex?'抓住关键了。':'换一个角度，再看一看。'}</strong><p>${safe(c.explanation)}</p><a href="${safe(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">继续阅读这条原理的资料 ↗</a>`;});
document.querySelector('.category-list').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b);});filterDeck();});
$('#prev-card').addEventListener('click',()=>{if(index>0){index--;render();$('#deck').focus();}});$('#next-card').addEventListener('click',()=>{if(index<deck.length-1){index++;render();$('#deck').focus();}});$('#shuffle-deck').addEventListener('click',()=>{for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}index=0;render();$('#deck').focus();});render();
})();
